/**
 * Kumva StartCampaign Node - Flow Setup & Context
 * Does NOT send messages. Prepares context for Send Message to initiate contact.
 */

require('dotenv').config();

module.exports = function(RED) {
  const crypto = require('crypto');
  const SessionManager = require('kumva-insights/utils/session-manager');
  const DataStorage = require('kumva-insights/utils/data-storage');
  const ConfigManager = require('kumva-insights/utils/config-manager');
  const helpers = require('kumva-insights/utils/helpers');

  let globalSessionManager = null;
  let globalDataStorage = null;
  const webhookManagers = new Map();
  const registeredPaths = new Map();

  async function initializeGlobals() {
    if (!globalSessionManager) {
      const configManager = new ConfigManager();
      globalSessionManager = new SessionManager(configManager.getRedisConfig());
      await globalSessionManager.initialize();
      globalDataStorage = new DataStorage(configManager.getStoragePath());
    }
    return { sessionManager: globalSessionManager, dataStorage: globalDataStorage };
  }

  class WebhookManager {
    constructor() {
      this.nodeRegistry = new Map(); // sessionId -> {callback, timeout}
    }
    registerWaitingNode(sessionId, callback, timeout) {
      this.nodeRegistry.set(sessionId, { callback, timeout });
    }
    unregisterWaitingNode(sessionId) {
      this.nodeRegistry.delete(sessionId);
    }
    getWaitingNode(sessionId) {
      return this.nodeRegistry.get(sessionId);
    }
    parseAfricasTalkingPayload(payload) {
      // SMS reply
      if (payload.text && payload.from) {
        return {
          type: 'sms',
          sessionId: payload.sessionId,
          phoneNumber: payload.from,
          content: payload.text
        };
      }
      // Voice DTMF
      if (payload.sessionId && (payload.dtmfInput || payload.durationInSeconds)) {
        return {
          type: 'dtmf',
          sessionId: payload.sessionId,
          phoneNumber: payload.callerNumber,
          content: payload.dtmfInput || ''
        };
      }
      return null;
    }
  }

  function registerWebhookEndpoint(webhookPath, webhookManager, flowId, apiKey) {
    if (registeredPaths.has(webhookPath)) {
      throw new Error(`Webhook "${webhookPath}" already registered by another flow`);
    }
    registeredPaths.set(webhookPath, flowId);

    if (!RED.httpAdmin._kumvaWebhooks) RED.httpAdmin._kumvaWebhooks = new Map();
    if (RED.httpAdmin._kumvaWebhooks.has(webhookPath)) return;

    RED.httpAdmin._kumvaWebhooks.set(webhookPath, true);

    RED.httpAdmin.post(webhookPath, async (req, res) => {
      try {
        const { sessionManager } = await initializeGlobals();
        const payload = req.body;
        const webhookMgr = webhookManagers.get(flowId);
        
        if (!webhookMgr) {
          return res.status(400).json({ success: false, error: 'No webhook manager' });
        }

        const response = webhookMgr.parseAfricasTalkingPayload(payload);
        if (!response) {
          return res.status(400).json({ success: false, error: 'Invalid payload' });
        }

        // Get waiting node for this sessionId
        const waitingNode = webhookMgr.getWaitingNode(response.sessionId);
        if (waitingNode?.callback) {
          setImmediate(() => {
            waitingNode.callback(response);
            webhookMgr.unregisterWaitingNode(response.sessionId);
          });
        }

        res.json({ success: true, sessionId: response.sessionId });
      } catch (error) {
        res.status(500).json({ success: false, error: error.message });
      }
    });
  }

  function KumvaStartCampaignNode(config) {
    RED.nodes.createNode(this, config);
    const node = this;
    const flowId = this.z;

    // Validate credentials
    if (!this.credentials?.username || !this.credentials?.apiKey) {
      node.status({ fill: 'red', shape: 'ring', text: 'Missing credentials' });
      return;
    }

    // Store config
    const initiationMode = config.initiationMode || 'outbound';
    const campaignType = config.campaignType || 'sms';
    const webhookPath = config.webhookPath || '/kumva/webhook';
    const baseUrl = process.env.KUMVA_WEBHOOK_BASE_URL;
    if (!baseUrl) {
      node.error('KUMVA_WEBHOOK_BASE_URL not set in environment');
      return;
    }
    const webhookUrl = baseUrl.replace(/\/$/, '') + webhookPath;

    const webhookManager = new WebhookManager();
    webhookManagers.set(flowId, webhookManager);

    try {
      registerWebhookEndpoint(webhookPath, webhookManager, flowId, this.credentials.apiKey);
      node.status({ fill: 'blue', shape: 'dot', text: `Listening: ${webhookPath}` });
    } catch (error) {
      node.error(error.message);
      node.status({ fill: 'red', shape: 'ring', text: 'Webhook error' });
      return;
    }

    // Export webhook manager globally
    RED.nodes.getFlowWebhookManager = function(fid) {
      return webhookManagers.get(fid);
    };

    initializeGlobals().catch(error => node.error(error.message));

    node.on('input', async function(msg) {
      try {
        // Validate required fields
        if (!msg.phoneNumber || !msg.campaignId) {
          return node.error('Missing phoneNumber or campaignId in message');
        }

        // Prepare campaign context
        // NOTE: NO sessionId created here - will come from Africa's Talking
        const campaignData = {
          campaignId: msg.campaignId,
          phoneNumber: msg.phoneNumber,
          campaignType: campaignType,
          initiationMode: initiationMode,
          contactData: msg.contactData || {},
          initialMessage: msg.initialMessage || '',
          webhookUrl: webhookUrl,
          credentials: {
            username: node.credentials.username,
            apiKey: node.credentials.apiKey
          },
          shortCode: config.shortCode || null,
          callerId: config.callerId || null,
          sessionTimeout: helpers.timeToSeconds(config.sessionTimeout || '3600s'),
          debugMode: config.debugMode || false
        };

        // Send context to next node (Send Message will initiate and get sessionId)
        const outputMsg = {
          ...msg,
          campaignId: msg.campaignId,
          phoneNumber: msg.phoneNumber,
          campaignData: campaignData,
          initiationMode: initiationMode,
          credentials: campaignData.credentials,
          webhookUrl: webhookUrl,
          _kumva: {
            campaignId: msg.campaignId,
            webhookUrl: webhookUrl,
            mode: initiationMode,
            timestamp: new Date().toISOString()
          }
        };

        node.status({ fill: 'green', shape: 'dot', text: 'Context ready' });
        node.send(outputMsg);

      } catch (error) {
        node.error(`StartCampaign: ${error.message}`);
        node.status({ fill: 'red', shape: 'ring', text: 'Error' });
      }
    });

    node.on('close', (done) => {
      webhookManagers.delete(flowId);
      registeredPaths.delete(webhookPath);
      done();
    });
  }

  // Webhook validation endpoint
  RED.httpAdmin.get('/kumva/webhook/validate/:path', (req, res) => {
    const path = '/' + req.params.path;
    if (registeredPaths.has(path)) {
      res.json({
        available: false,
        message: `Webhook path already in use`
      });
    } else {
      res.json({
        available: true,
        message: 'Webhook path available'
      });
    }
  });

  RED.nodes.registerType('kumva-start-campaign', KumvaStartCampaignNode, {
    credentials: {
      username: { type: 'text' },
      apiKey: { type: 'password' }
    }
  });
};